import math


def best_circular_selection(values: list[int], k: int) -> int:
    n = len(values)

    if k == 0:
        return 0
    if k < 0:
        raise ValueError("k must be non-negative")
    if n == 1:
        if k == 1:
            return values[0]
        else:
            raise ValueError(f"Cannot choose {k} elements from 1 element.")

    # For a circle of size n >= 2, at most n // 2 non-adjacent elements can be chosen.
    if k > n // 2:
        raise ValueError(
            f"Cannot choose {k} non-adjacent elements from a circle of size {n}."
        )

    def solve_linear(arr: list[int], target_k: int) -> float:
        if target_k == 0:
            return 0
        m = len(arr)
        # In a linear array of size m, at most (m + 1) // 2 elements can be chosen.
        if target_k > (m + 1) // 2:
            return -math.inf

        # prev2 corresponds to dp[i-2], prev1 corresponds to dp[i-1]
        prev2 = [-math.inf] * (target_k + 1)
        prev1 = [-math.inf] * (target_k + 1)
        prev2[0] = 0
        prev1[0] = 0

        if m >= 1:
            prev1[1] = arr[0]

        for i in range(1, m):
            val = arr[i]
            # Compute current DP states: max(skip current element, take current element)
            curr = [0] + [
                a if a > b + val else b + val
                for a, b in zip(prev1[1:], prev2[:-1])
            ]
            prev2, prev1 = prev1, curr

        return prev1[target_k]

    # Case 1: Do not pick values[0]. Pick k elements from values[1:]
    ans1 = solve_linear(values[1:], k)

    # Case 2: Pick values[0]. Pick k-1 elements from values[2:-1]
    ans2 = values[0] + solve_linear(values[2:-1], k - 1)

    ans = max(ans1, ans2)
    return int(ans)

def smallest_balanced(s: str) -> str:
    n = len(s)

    # A balanced string must have an even length.
    if n % 2 != 0:
        raise ValueError("String length must be even to be balanced.")

    open_needed = n // 2 - s.count('(')
    close_needed = n // 2 - s.count(')')

    # If there are already too many '(' or ')', it's impossible to balance.
    if open_needed < 0 or close_needed < 0:
        raise ValueError("Too many fixed '(' or ')' characters.")

    res = []
    balance = 0

    for char in s:
        if char == '?':
            # Greedily place '(' as early as possible
            if open_needed > 0:
                char = '('
                open_needed -= 1
            else:
                char = ')'

        if char == '(':
            balance += 1
        else:
            balance -= 1

        # Running count of '(' minus ')' can never go negative
        if balance < 0:
            raise ValueError("Cannot form a balanced string.")

        res.append(char)

    return "".join(res)

from typing import Iterable


def min_insertions(s: str, allowed: Iterable[str]) -> int:
    n = len(s)
    if n <= 1:
        return 0

    allowed_set = set(allowed)
    INF = float("inf")

    # dp[i][j] will store the min insertions for substring s[i..j]
    # Base cases: dp[i][i] = 0 (length 1) and dp[i][i-1] = 0 (length 0)
    dp = [[0] * n for _ in range(n)]

    # Iterate over the length of the substring from 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            res = INF

            # Option 1: The ends already match
            if s[i] == s[j]:
                res = dp[i + 1][j - 1]

            # Option 2: Insert s[i] at the right end to match s[i]
            if s[i] in allowed_set:
                if dp[i + 1][j] + 1 < res:
                    res = dp[i + 1][j] + 1

            # Option 3: Insert s[j] at the left end to match s[j]
            if s[j] in allowed_set:
                if dp[i][j - 1] + 1 < res:
                    res = dp[i][j - 1] + 1

            dp[i][j] = res

    ans = dp[0][n - 1]
    return -1 if ans == INF else ans

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)

        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)

        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)

    return order

import re

_AMOUNT_RE = re.compile(r"\A([0-9]+)(?:\.([0-9]{1,2}))?\Z")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount_str = tx["amount"]
        if not isinstance(amount_str, str):
            raise ValueError("amount must be a string")

        match = _AMOUNT_RE.match(amount_str)
        if not match:
            raise ValueError(f"invalid amount format: {amount_str!r}")

        dollars_str, frac_str = match.groups()
        cents = int(dollars_str) * 100
        if frac_str is not None:
            # Pad single-digit fractional part (e.g., "5" -> "50")
            cents += int(frac_str.ljust(2, "0"))

        if cents <= 0:
            raise ValueError("amount must be positive")

        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents

    return balances

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])

    # 1. Validate bounds for all hunks
    for start, delete, _ in ordered:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")

    # 2. Check for conflicts (same start position or overlapping delete ranges)
    for i in range(1, len(ordered)):
        prev_start, prev_delete, _ = ordered[i - 1]
        curr_start, _, _ = ordered[i]
        if curr_start == prev_start or curr_start < prev_start + prev_delete:
            raise ValueError("conflicting hunks")

    # 3. Apply hunks in reverse order so earlier indices are not shifted
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start : start + delete] = list(insert)

    return result

