from typing import Any, Hashable, List, Tuple


class CountingBag:
    """A multiset (bag) of hashable items that tracks counts and entry order."""

    def __init__(self) -> None:
        # Maps item -> count.
        # Relies on Python 3.7+ dict insertion-order preservation to track entry moments.
        self._counts: dict[Hashable, int] = {}
        self._total: int = 0

    def add(self, item: Hashable) -> int:
        """Add one occurrence of `item` and return its new count."""
        new_count = self._counts.get(item, 0) + 1
        self._counts[item] = new_count
        self._total += 1
        return new_count

    def discard(self, item: Hashable) -> bool:
        """Remove one occurrence of `item`.

        Return True if removed, False if not present.
        """
        if item not in self._counts:
            return False

        count = self._counts[item]
        if count == 1:
            # Removing the key completely forgets its insertion order
            del self._counts[item]
        else:
            self._counts[item] = count - 1

        self._total -= 1
        return True

    def count(self, item: Hashable) -> int:
        """Return the current count of `item` (0 if absent)."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Return the total number of occurrences across all items."""
        return self._total

    def distinct(self) -> int:
        """Return the number of distinct items currently present."""
        return len(self._counts)

    def most_common(self, k: int) -> List[Tuple[Hashable, int]]:
        """Return the `k` items with the highest counts as (item, count) tuples.

        Ordered by count descending, with ties broken by earliest entry moment.
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0 or not self._counts:
            return []

        # Since self._counts preserves insertion order and Python's sorting/heapq
        # routines are stable, sorting solely by -count naturally breaks ties
        # by earlier entry moment.
        if k >= len(self._counts):
            return sorted(self._counts.items(), key=lambda x: -x[1])

        return heapq.nsmallest(k, self._counts.items(), key=lambda x: -x[1])

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int):
        # Note: in Python, isinstance(True, int) is True, so we explicitly exclude bool
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")

        self._capacity = capacity
        # Maps key -> (value, expiration_time)
        # expiration_time is a float/int, or None if the entry never expires
        self._cache = OrderedDict()

        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now: float) -> None:
        """Remove all entries that have expired at or before `now`."""
        expired_keys = [
            k for k, (_, exp) in self._cache.items()
            if exp is not None and now >= exp
        ]
        for k in expired_keys:
            del self._cache[k]
            self._expirations += 1

    def put(self, key, value, now: float, ttl: float = None) -> None:
        if ttl is not None:
            if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or ttl <= 0:
                raise ValueError("ttl must be a positive number or None")

        self._purge(now)

        exp = (now + ttl) if ttl is not None else None

        if key in self._cache:
            # Update existing key and mark as most-recently-used
            self._cache[key] = (value, exp)
            self._cache.move_to_end(key)
        else:
            # Evict least-recently-used if at capacity
            if len(self._cache) >= self._capacity:
                self._cache.popitem(last=False)
                self._evictions += 1
            # Insert as most-recently-used
            self._cache[key] = (value, exp)

    def get(self, key, now: float):
        self._purge(now)

        if key in self._cache:
            self._hits += 1
            self._cache.move_to_end(key)
            return self._cache[key][0]
        else:
            self._misses += 1
            return None

    def stats(self) -> dict:
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self) -> int:
        return len(self._cache)

class Leaderboard:
    def __init__(self):
        # Maps player -> (best_score, timestamp)
        self._records: dict[str, tuple[int, int]] = {}
        self._timer: int = 0

    def submit(self, player: str, score: int) -> bool:
        """Record an attempt. Returns True if it improves the player's best."""
        if player not in self._records or score > self._records[player][0]:
            self._timer += 1
            self._records[player] = (score, self._timer)
            return True
        return False

    def best(self, player: str) -> int:
        """Return the player's best score. Raises KeyError for unknown players."""
        if player not in self._records:
            raise KeyError(f"Unknown player: {player}")
        return self._records[player][0]

    def rank(self, player: str) -> int:
        """Return the standard competition rank (1 + count of strictly better players)."""
        target_score = self.best(player)  # Also handles the KeyError check
        return 1 + sum(
            1 for score, _ in self._records.values() if score > target_score
        )

    def top(self, k: int) -> list[tuple[str, int]]:
        """Return the top k players as (player, best) tuples."""
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        # Sort by best score descending (-score), then by timestamp ascending (timestamp)
        sorted_players = sorted(
            self._records.items(),
            key=lambda item: (-item[1][0], item[1][1])
        )

        return [(player, score) for player, (score, _) in sorted_players[:k]]

    def player_count(self) -> int:
        """Return the number of distinct players seen."""
        return len(self._records)

from typing import Any


class UndoStack:
    """A LIFO stack of arbitrary Python values whose mutating operations can be undone."""

    def __init__(self) -> None:
        self._stack: list[Any] = []
        # History stores tuples of ('push',) or ('pop', popped_value)
        self._history: list[tuple[str, ...]] = []

    def push(self, x: Any) -> None:
        """Push x onto the top of the stack."""
        self._stack.append(x)
        self._history.append(("push",))

    def pop(self) -> Any:
        """Remove and return the top value. Raise IndexError if the stack is empty."""
        if not self._stack:
            raise IndexError("pop from empty UndoStack")
        val = self._stack.pop()
        self._history.append(("pop", val))
        return val

    def peek(self) -> Any:
        """Return the top value without removing it. Raise IndexError if the stack is empty."""
        if not self._stack:
            raise IndexError("peek from empty UndoStack")
        return self._stack[-1]

    def undo(self) -> None:
        """Reverse the most recent successful push or pop that has not already been undone."""
        if not self._history:
            raise RuntimeError("nothing left to undo")

        action = self._history.pop()
        if action[0] == "push":
            self._stack.pop()
        elif action[0] == "pop":
            self._stack.append(action[1])

    def __len__(self) -> int:
        """Return the number of values currently on the stack."""
        return len(self._stack)

from typing import Any, Hashable


class VersionedKV:
    """A key-value store with commit snapshots, point-in-time reads, and rollback."""

    def __init__(self) -> None:
        self._working: dict[Hashable, Any] = {}
        self._snapshots: list[dict[Hashable, Any]] = []

    def set(self, key: Hashable, value: Any) -> None:
        """Write a key-value pair to the working state."""
        self._working[key] = value

    def delete(self, key: Hashable) -> None:
        """Remove a key from the working state; raise KeyError if absent."""
        del self._working[key]

    def get(self, key: Hashable) -> Any:
        """Read a key's value from the working state; raise KeyError if absent."""
        return self._working[key]

    def has(self, key: Hashable) -> bool:
        """Return True if the key is present in the working state, False otherwise."""
        return key in self._working

    def commit(self) -> int:
        """Snapshot the working state and return the new version number."""
        self._snapshots.append(self._working.copy())
        return len(self._snapshots)

    def get_at(self, key: Hashable, version: int) -> Any:
        """Read a key's value from a specific committed version.

        Raises ValueError if the version is out of range (must be 1 <= version <= latest()).
        Raises KeyError if the key was not present in that snapshot.
        """
        if isinstance(version, bool) or not isinstance(version, int):
            raise ValueError("Version must be an integer")
        if not (1 <= version <= len(self._snapshots)):
            raise ValueError(
                f"Invalid version: {version}. Must be between 1 and {self.latest()}."
            )

        snapshot = self._snapshots[version - 1]
        return snapshot[key]

    def rollback(self, version: int) -> None:
        """Replace the working state with a copy of the specified version's snapshot.

        Version 0 resets the working state to an empty store.
        Raises ValueError if the version is out of range (must be 0 <= version <= latest()).
        """
        if isinstance(version, bool) or not isinstance(version, int):
            raise ValueError("Version must be an integer")
        if not (0 <= version <= len(self._snapshots)):
            raise ValueError(
                f"Invalid version: {version}. Must be between 0 and {self.latest()}."
            )

        if version == 0:
            self._working.clear()
        else:
            self._working = self._snapshots[version - 1].copy()

    def latest(self) -> int:
        """Return the number of commits made so far."""
        return len(self._snapshots)

import math


def rank_scores(scores: list) -> list[int]:
    """Assigns standard competition ranks ("1224" ranking) to a list of numeric scores.

    Higher scores rank better (rank 1 is the highest).
    """
    if not scores:
        return []

    # Check for NaN values, which are not comparable and cannot be ranked.
    for score in scores:
        if math.isnan(score):
            raise ValueError("Scores cannot contain NaN")

    # Sort scores in descending order without mutating the original list.
    sorted_scores = sorted(scores, reverse=True)

    # Map each unique score to its competition rank.
    # Iterating with 1-based indexing naturally gives the "1224" rank
    # upon seeing a score for the first time.
    score_to_rank = {}
    for rank, score in enumerate(sorted_scores, start=1):
        if score not in score_to_rank:
            score_to_rank[score] = rank

    # Map the original scores to their calculated ranks.
    return [score_to_rank[score] for score in scores]

import unicodedata


def truncate_display(s: str, width: int) -> str:
    """Truncates a string to a maximum display width measured in user-perceived

    characters, keeping Unicode combining marks attached to their base
    characters.
    """
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    combining_categories = {"Mn", "Mc", "Me"}
    unit_count = 0

    for i, ch in enumerate(s):
        is_combining = unicodedata.category(ch) in combining_categories

        # A new unit starts at the very first character (even if it's a combining mark)
        # or at any non-combining character.
        if i == 0 or not is_combining:
            unit_count += 1
            if unit_count > width:
                return s[:i]

    return s

import math


def kth_root_floor(n: int, k: int) -> int:
    """Return the floor of the k-th root of a nonnegative integer n,

    computed using only exact integer arithmetic.
    """
    if n < 0:
        raise ValueError("n must be a nonnegative integer (n >= 0).")
    if k < 1:
        raise ValueError("k must be a positive integer (k >= 1).")

    # Base cases
    if n <= 1 or k == 1:
        return n
    if k == 2:
        return math.isqrt(n)

    # Since n >= 2, if 2**k > n, the floor of the k-th root must be 1.
    # Because 2**k has bit length k + 1, we know 2**k > n whenever k >= n.bit_length().
    # This check prevents computing massive powers when k is very large.
    bit_len = n.bit_length()
    if k >= bit_len:
        return 1

    # Establish tight binary search bounds using the bit length of n.
    # Since 2**(bit_len - 1) <= n < 2**bit_len, we know that:
    # 2**((bit_len - 1) // k) <= n**(1/k) < 2**((bit_len - 1) // k + 1)
    low = 1 << ((bit_len - 1) // k)
    high = low << 1

    # Binary search within [low, high)
    while low < high - 1:
        mid = (low + high) >> 1
        if mid**k <= n:
            low = mid
        else:
            high = mid

    return low

def weighted_median(values: list, weights: list) -> float:
    """Returns the lower weighted median of a dataset."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length.")

    if not values:
        raise ValueError("values and weights cannot be empty.")

    if any(w < 0 for w in weights):
        raise ValueError("All weights must be non-negative.")

    total_weight = sum(weights)
    if total_weight <= 0:
        raise ValueError("The sum of weights must be strictly positive.")

    # Pair values with weights and sort by value ascending.
    # Filtering out zero weights (w > 0) ensures that zero-weight entries
    # never prematurely trigger the threshold (e.g., if W/2 is tiny and < 1e-9).
    sorted_pairs = sorted(
        ((v, w) for v, w in zip(values, weights) if w > 0), key=lambda x: x[0]
    )

    threshold = (total_weight / 2.0) - 1e-9
    cumulative_weight = 0.0

    for val, weight in sorted_pairs:
        cumulative_weight += weight
        if cumulative_weight >= threshold:
            return val

    # Fallback in case of extreme floating-point inaccuracies
    return sorted_pairs[-1][0]

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(data)
    q = len(queries)
    if q == 0:
        return []
    if n == 0:
        return [0] * q

    # Group queries by their right endpoint r.
    # Since 0 <= l <= r <= n, queries with l == r (or r < 2) always have answer 0.
    queries_at_r = [[] for _ in range(n + 1)]
    for idx, (l, r) in enumerate(queries):
        if r - l >= 2:
            queries_at_r[r].append((l, idx))

    # Fenwick tree (1-indexed, size n + 1)
    bit = [0] * (n + 1)

    # Dictionaries to store the 1-based indices of the last and second-to-last occurrences
    last1 = {}
    last2 = {}

    ans = [0] * q
    total_active = 0  # Total number of distinct elements that have appeared at least twice so far

    # Sweep r from 1 to n (where i = r - 1 is the 0-based index in data, and r is the 1-based index)
    for r, v in enumerate(data, 1):
        p1 = last1.get(v, 0)
        if p1:
            p2 = last2.get(v, 0)
            if p2:
                # Remove the old second-to-last occurrence from BIT
                idx = p2
                while idx <= n:
                    bit[idx] -= 1
                    idx += idx & -idx
            else:
                # v is appearing for the 2nd time overall, increasing total recurring elements
                total_active += 1

            # Add the new second-to-last occurrence (which is p1) to BIT
            idx = p1
            while idx <= n:
                bit[idx] += 1
                idx += idx & -idx

            last2[v] = p1
        last1[v] = r

        # Answer all queries ending at r
        if queries_at_r[r]:
            for l, q_idx in queries_at_r[r]:
                # Count how many active second-to-last occurrences are strictly before l (1-based index <= l)
                 prefix_sum = 0
                idx = l
                while idx > 0:
                    prefix_sum += bit[idx]
                    idx -= idx & -idx
                ans[q_idx] = total_active - prefix_sum

    return ans

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    summaries = {}

    for i, row in enumerate(rows):
        # a. not a tuple or wrong length -> TypeError
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}: must be a tuple of length 3")

        category, amount, refunded = row

        # b. category not a str, or empty str -> ValueError
        if not isinstance(category, str) or len(category) == 0:
            raise ValueError(f"row {i}: category must be a non-empty str")

        # c. amount is a bool or not int/float -> TypeError
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}: amount must be an int or float (not bool)")

        # d. amount < 0 -> ValueError (also handles NaN safely if needed, though < 0 is specified)
        if not (amount >= 0):
            raise ValueError(f"row {i}: amount must be >= 0")

        # e. refunded not a bool -> TypeError
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}: refunded must be a bool")

        amt_float = float(amount)

        if category not in summaries:
            summaries[category] = {
                "count": 1,
                "gross": amt_float,
                "net": 0.0 if refunded else amt_float,
                "largest": amt_float,
            }
        else:
            cat_summary = summaries[category]
            cat_summary["count"] += 1
            cat_summary["gross"] += amt_float
            if not refunded:
                cat_summary["net"] += amt_float
            if amt_float > cat_summary["largest"]:
                cat_summary["largest"] = amt_float

    return summaries

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    if (
        isinstance(low, bool)
        or not isinstance(low, (int, float))
        or isinstance(high, bool)
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, val in enumerate(values):
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise TypeError(f"invalid element at index {i}")

        if val < low:
            result.append(low)
        elif val > high:
            result.append(high)
        else:
            result.append(val)

    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Stack stores pairs of (iterator, current_depth)
    stack = [(iter(nested), 0)]

    while stack:
        current_iter, depth = stack[-1]
        for item in current_iter:
            if isinstance(item, list) and depth < max_depth:
                stack.append((iter(item), depth + 1))
                break
            else:
                result.append(item)
        else:
            stack.pop()

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if text == "" or text.isspace():
        raise ValueError("empty duration")

    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    last_unit_index = -1
    total_seconds = 0
    current_digits = []

    for ch in text:
        if "0" <= ch <= "9":
            current_digits.append(ch)
        elif ch in units:
            if not current_digits:
                raise ValueError("malformed duration")
            unit_index, multiplier = units[ch]
            if unit_index <= last_unit_index:
                raise ValueError("malformed duration")
            last_unit_index = unit_index
            value = int("".join(current_digits))
            total_seconds += value * multiplier
            current_digits = []
        else:
            raise ValueError("malformed duration")

    if current_digits or last_unit_index == -1:
        raise ValueError("malformed duration")

    return total_seconds

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    valid_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"
    result = []
    n = len(template)
    i = 0

    while i < n:
        ch = template[i]
        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                result.append("{")
                i += 2
            else:
                start_pos = i
                i += 1
                name_chars = []
                while i < n and template[i] != "}":
                    if template[i] not in valid_chars:
                        raise ValueError("invalid placeholder at position " + str(start_pos))
                    name_chars.append(template[i])
                    i += 1

                if i == n:
                    raise ValueError("unclosed placeholder at position " + str(start_pos))

                # At this point, template[i] == "}"
                if not name_chars:
                    raise ValueError("empty placeholder at position " + str(start_pos))

                name = "".join(name_chars)
                if name not in context:
                    raise KeyError(name)

                result.append(str(context[name]))
                i += 1
        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                result.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            result.append(ch)
            i += 1

    return "".join(result)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")

    if len(tokens) == 0:
        raise ValueError("empty expression")

    stack = []
    operators = ("+", "-", "*", "/")

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i} is not a string")

        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")

            right = stack.pop()
            left = stack.pop()

            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            elif token == "/":
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                # Integer division truncated toward zero without float limits
                sign = -1 if (left < 0) ^ (right < 0) else 1
                stack.append(sign * (abs(left) // abs(right)))
        else:
            # Validate integer literal: optional '+' or '-' followed by >= 1 ASCII digits
            digits_part = token
            if digits_part.startswith("+") or digits_part.startswith("-"):
                digits_part = digits_part[1:]

            if not digits_part or not (
                digits_part.isascii() and digits_part.isdigit()
            ):
                raise ValueError(f"unknown token '{token}' at token {i}")

            stack.append(int(token))

    if len(stack) > 1:
        raise ValueError("leftover operands on stack")

    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment in path")

    def is_ascii_digits(s):
        if not s:
            return False
        if not ("0" <= s[0] <= "9"):
            return False
        if len(s) == 1:
            return True
        return is_ascii_digits(s[1:])

    def is_valid_int_literal(s):
        if s.startswith("-"):
            return is_ascii_digits(s[1:])
        return is_ascii_digits(s)

    def traverse(node, segs):
        if not segs:
            return node

        seg = segs[0]
        rest = segs[1:]

        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return traverse(node[seg], rest)

        if isinstance(node, list):
            if not is_valid_int_literal(seg):
                raise ValueError(f"invalid index: {seg}")
            idx = int(seg)
            if idx < -len(node) or idx >= len(node):
                raise IndexError(f"list index out of range: {seg}")
            return traverse(node[idx], rest)

        raise TypeError(f"cannot descend into {type(node).__name__} with segment '{seg}'")

    return traverse(data, segments)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0 or not items:
        return []

    counts = {}
    order = []
    for item in items:
        if item not in counts:
            counts[item] = 1
            order.append(item)
        else:
            counts[item] += 1

    candidates = [(val, counts[val], idx) for idx, val in enumerate(order)]
    result = []
    limit = k if k < len(candidates) else len(candidates)

    for _ in range(limit):
        best_pos = 0
        for i in range(1, len(candidates)):
            curr_val, curr_cnt, curr_idx = candidates[i]
            best_val, best_cnt, best_idx = candidates[best_pos]
            if curr_cnt > best_cnt or (
                curr_cnt == best_cnt and curr_idx < best_idx
            ):
                best_pos = i

        chosen = candidates.pop(best_pos)
        result.append((chosen[0], chosen[1]))

    return result
